patch.replacementBlock:
if(pushRows.length>2)throw Error('Push-only experiment exceeded two vertical rows');
const initialVelocity=this.velocity;
const prepareCandidate=mask=>{
  const candidateA=A.map(row=>row.slice()),candidateRhs=rhs.slice();
  for(let r=0;r<pushRows.length;r++)if(!(mask&(1<<r))){
    const p=pushRows[r];for(let i=2;i<N;i++){
      candidateRhs[i]-=h*p.row[i]*p.alpha;
      for(let k=2;k<N;k++)candidateA[i][k]-=h*p.beta*p.row[i]*p.row[k];
    }
  }
  const L=factor(candidateA),velocity=solve(L,candidateRhs);
  for(let i=0;i<N;i++){const cap=this.passive?(i<2?2:6):(i<2?4:14);velocity[i]=clamp(velocity[i],-cap,cap);}
  try{
    this.velocity=velocity;
    const contacts=this.#contactRows(state,true,h,false);
    for(let i=1;i<N;i++){
      const proposed=this.q[i]+h*velocity[i],bounded=clamp(proposed,this.limits[i][0],this.limits[i][1]);
      if(proposed!==bounded){contacts.rows.push(STOP_ROWS[i][1]);contacts.values.push((bounded-this.q[i])/h-velocity[i]);}
    }
    const reaction=this.#constraintDelta(L,contacts.rows,contacts.values);
    for(let i=0;i<N;i++)velocity[i]+=reaction.delta[i];
    const floorContacts=this.#contactRows(state,true,h,false),floorReactions={};
    const floorDelta=this.#unilateralDelta(L,floorContacts.rows,floorContacts.values,this.#floorInequalities(state,true,h),floorReactions);
    for(let i=0;i<N;i++)velocity[i]+=floorDelta[i];
    const forces=pushRows.map((p,r)=>{const raw=p.alpha-p.beta*dot(p.row,velocity),active=!!(mask&(1<<r));return {key:p.key,active,raw,applied:active?raw:0,strength:p.strength,damping:p.damping,error:p.error,speed:p.speed,supportWeight:p.supportWeight,Jv:dot(p.row,velocity)};});
    return {mask,L,velocity,contacts,reaction,floorContacts,floorReactions,forces,valid:forces.every(f=>f.active?f.raw>=-1e-8:f.raw<=1e-8)};
  }finally{this.velocity=initialVelocity;}
};
const trials=[];let selected=null;
for(let mask=(1<<pushRows.length)-1;mask>=0;mask--){const trial=prepareCandidate(mask);trials.push({mask,forces:trial.forces,valid:trial.valid});if(trial.valid){selected=trial;break;}}
if(!selected)throw Error('Push-only active set has no complementarity-valid solution: '+JSON.stringify(trials));
const velocityFactor=selected.L,massFactor=this.#massFactor(state);this.velocity=selected.velocity;
this.#recordTangentialReaction(selected.contacts.footRows,selected.reaction.lambda,h);
for(const c of this.contacts)c.groundReaction=(c.groundReaction??0)+(selected.floorReactions[c.key]??0)/h;
this.#recordTangentialReaction(selected.floorContacts.footRows,selected.floorReactions.constraints,h);
for(let r=0;r<pushRows.length;r++)if(!(selected.mask&(1<<r)))for(let i=2;i<N;i++)this.lastMotor[i]-=pushRows[r].row[i]*pushRows[r].oldForce;
this.__pushAudit={time:this.time,enabled:pushOnly,rows:pushRows.length,mask:selected.mask,forces:selected.forces,trials:trials.length,stage:'velocity integrated before nonlinear position repair',targetHip:motorTarget[1],hip:state.points.hip.y};
